def fixture():
    return json.loads(zlib.decompress(base64.b85decode(_FIXTURE_B85)))
def encoded(value):
    return (json.dumps(value, sort_keys=True, indent=2) + "\n").encode()
def line(value):
    return (json.dumps(value, sort_keys=True) + "\n").encode()
def identity(raw):
    return {"bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}


class PaidCpuCiAdmission(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="paid-ci-admission-")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.data = fixture()
        self.index = 0

    def capture(self, name="live-clock3-einval"):
        self.index += 1
        folder = self.root / str(self.index)
        folder.mkdir()
        for key, text in self.data["captures"][name].items():
            (folder / key).write_bytes(base64.b64decode(text))
        report = ci.read(folder / "report.json")
        return folder, report

    def save(self, folder, report, events=None):
        if events is not None:
            raw = b"".join((json.dumps(row, sort_keys=True) + "\n").encode() for row in events)
            (folder / "events.jsonl").write_bytes(raw)
            report["events"] = identity(raw)
        (folder / "report.json").write_bytes(encoded(report))

    def check(self, folder, report, fault=None, disabled=True):
        if fault is None and disabled:
            fault = {"clock_error": 22, "clock_roles": [2, 3], "clock_when": 3}
        return ci.fault_capture(folder, report, Path(report["argv"][0]),
                                self.data["executable"], fault, disabled)

    def test_actual_recorded_fault_and_both_platform_baselines(self):
        for name in ("live-clock3-einval", "normal-vdso-baseline", "raw-fallback-baseline"):
            with self.subTest(name=name):
                folder, report = self.capture(name)
                ci.fault_capture(folder, report, Path(report["argv"][0]), self.data["executable"],
                                 report["fault"], report["disable_vdso"])

    def test_failure_or_unreaped_capture_cannot_borrow_valid_observation(self):
        changes = [("status", "FAIL"), ("exit_code", 1), ("signal", 9),
                   ("complete_owned_process_reaped", False), ("executable_after", "FAIL"),
                   ("failure", "retained actual failure"), ("failure_cleanup", {"complete": False})]
        for key, value in changes:
            with self.subTest(key=key):
                folder, report = self.capture()
                report[key] = value
                self.save(folder, report)
                with self.assertRaisesRegex(ValueError, "failed or did not fully reap"):
                    self.check(folder, report)

    def test_actual_executable_command_and_profile_are_not_replaceable(self):
        for key in ("argv", "executable_before", "disable_vdso", "fault"):
            with self.subTest(key=key):
                folder, report = self.capture()
                if key == "argv":
                    report[key][0] = "/unbound/other-test-binary"
                elif key == "executable_before":
                    report[key]["sha256"] = "0" * 64
                elif key == "disable_vdso":
                    report[key] = False
                else:
                    report[key]["clock_when"] = 4
                self.save(folder, report)
                binary = Path(self.data["captures_binary"])
                with self.assertRaisesRegex(ValueError, "command, or injection profile"):
                    ci.fault_capture(folder, report, binary, self.data["executable"],
                                     {"clock_error": 22, "clock_roles": [2, 3], "clock_when": 3}, True)

    def test_all_actual_raw_streams_are_bound(self):
        for stream in ("stdout.raw", "stderr.raw", "events.jsonl"):
            with self.subTest(stream=stream):
                folder, report = self.capture()
                with (folder / stream).open("ab") as output:
                    output.write(b"\n")
                with self.assertRaisesRegex(ValueError, "raw stream changed"):
                    self.check(folder, report)

    def test_coherent_auxv_metadata_cannot_hide_another_write(self):
        folder, report = self.capture()
        events = [json.loads(line) for line in (folder / "events.jsonl").read_text().splitlines()]
        raw = bytearray.fromhex(report["auxv"]["auxv_after_hex"])
        raw[24] ^= 1
        report["auxv"]["auxv_after_hex"] = raw.hex()
        next(row for row in events if row["kind"] == "exec")["auxv"] = copy.deepcopy(report["auxv"])
        self.save(folder, report, events)
        with self.assertRaisesRegex(ValueError, "more than its one vDSO advertisement"):
            self.check(folder, report)

    def test_task_calls_cannot_cross_actual_birth_and_terminal_boundaries(self):
        for before in (True, False):
            with self.subTest(before_birth=before):
                folder, report = self.capture()
                events = [json.loads(line) for line in (folder / "events.jsonl").read_text().splitlines()]
                child = next(int(tid) for tid, row in report["roster"].items()
                             if row["parent"] is not None and row["terminal"]["sequence"] < len(events))
                birth = report["roster"][str(child)]["birth"]
                terminal = report["roster"][str(child)]["terminal"]["sequence"]
                event = next(row for row in events if row["kind"] == "syscall-entry"
                             and (row["sequence"] < birth if before else row["sequence"] > terminal))
                event["tid"] = child
                self.save(folder, report, events)
                with self.assertRaisesRegex(ValueError, "birth/terminal lifetime"):
                    self.check(folder, report)

    def test_complete_clock_and_injection_receipts_are_required(self):
        for key in ("actual_clock_calls", "injections"):
            with self.subTest(key=key):
                folder, report = self.capture()
                report[key].pop()
                self.save(folder, report)
                with self.assertRaises(ValueError):
                    self.check(folder, report)
        folder, report = self.capture()
        report["injections"][0]["actual_skipped_result"] = -1
        self.save(folder, report)
        with self.assertRaisesRegex(ValueError, "selected syscall"):
            self.check(folder, report)

    def test_count_uses_complete_actual_events_without_a_scheduling_constant(self):
        native = copy.deepcopy(self.data["budget"])
        self.assertEqual(ci.budget_operations(native), 83)
        # This is only a count-admission fixture, not a new native execution:
        # a later valid cold history may legitimately contain more operations.
        alternate = copy.deepcopy(native)
        alternate["owners"][-1]["trace"]["replay"]["operations"].append(
            copy.deepcopy(alternate["owners"][-1]["trace"]["replay"]["operations"][0]))
        alternate["actual_budget_operations"] += 1
        self.assertEqual(ci.budget_operations(alternate), 84)
        changed = copy.deepcopy(native)
        changed["actual_budget_operations"] = 84
        with self.assertRaises(ValueError):
            ci.budget_operations(changed)
        changed = copy.deepcopy(native)
        changed["actual_budget_operations"] = True
        with self.assertRaises(ValueError):
            ci.budget_operations(changed)
        changed = copy.deepcopy(native)
        changed["owners"].pop()
        with self.assertRaises(ValueError):
            ci.budget_operations(changed)

    def test_full_compiler_version_and_explicit_tools_are_required(self):
        original = copy.deepcopy(self.data["standard_record"])
        source = {"standard_library": copy.deepcopy(original["standard_library"])}
        abi = ci.read(HERE / "abi.json")
        ci.standard_binding(original, source, abi)
        for name in ("version", "wrapper", "cargo", "stdlib-roster"):
            with self.subTest(name=name):
                changed = copy.deepcopy(original)
                if name == "version":
                    changed["standard_library"]["compiler"] = changed["standard_library"]["compiler"].replace("1.95.0", "1.99.1")
                elif name == "wrapper":
                    changed["explicit_compiler_environment"]["RUSTC_WRAPPER"] = "/unbound/wrapper"
                elif name == "cargo":
                    changed["standard_library"]["cargo_executable"]["path"] = "/unbound/cargo"
                else:
                    changed["standard_library"]["binaries"].pop(next(iter(changed["standard_library"]["binaries"])))
                with self.assertRaises(ValueError):
                    ci.standard_binding(changed, {"standard_library": copy.deepcopy(changed["standard_library"])}, abi)

    def executable_fixture(self):
        directory = self.root / "executable"
        directory.mkdir()
        binary = directory / "original-test-binary"
        raw = b"independent file metadata fixture; never executed\n"
        binary.write_bytes(raw)
        binary.chmod(0o500)
        compiled = str(directory / "outside-cargo-output")
        original = {"executable": {"path": str(binary), **identity(raw)},
                    "compiled_executable": {"path": compiled, **identity(raw)}}
        stage = directory / "cargo-original-test-build"
        stage.mkdir()
        event = {"reason": "compiler-artifact", "target": {"name": "trnm_pon_node", "kind": ["lib"]},
                 "profile": {"test": True}, "executable": compiled}
        (stage / "stdout.raw").write_bytes(line(event))
        return directory, binary, original, event

    def test_independent_binary_is_read_only_single_link_and_actual_test_artifact(self):
        directory, binary, original, event = self.executable_fixture()
        ci.independent_executable(directory, original)
        binary.chmod(0o700)
        with self.assertRaisesRegex(ValueError, "mutable/aliased"):
            ci.independent_executable(directory, original)
        binary.chmod(0o500)
        alias = directory / "alias"
        alias.hardlink_to(binary)
        with self.assertRaisesRegex(ValueError, "mutable/aliased"):
            ci.independent_executable(directory, original)
        alias.unlink()
        original["compiled_executable"]["sha256"] = "0" * 64
        with self.assertRaisesRegex(ValueError, "Cargo test-library artifact"):
            ci.independent_executable(directory, original)

    def test_build_script_artifact_is_distinct_from_real_test_library(self):
        directory, binary, original, event = self.executable_fixture()
        script = copy.deepcopy(event)
        script["target"]["kind"] = ["custom-build"]
        script["executable"] = "/not-a-library/build-script"
        raw = directory / "cargo-original-test-build/stdout.raw"
        raw.write_bytes(line(script) + line(event))
        ci.independent_executable(directory, original)
        raw.write_bytes(line(event) + line(event))
        with self.assertRaisesRegex(ValueError, "one actual Cargo test-library artifact"):
            ci.independent_executable(directory, original)

    def test_settled_process_and_raw_outputs_cannot_drift_after_success(self):
        label = "mandatory-original-linux-clocks"
        folder = self.root / label
        folder.mkdir()
        row = copy.deepcopy(self.data["positive_stage"]["receipt"])
        (folder / "receipt.json").write_bytes(encoded(row))
        for name in ("stdout.raw", "stderr.raw"):
            (folder / name).write_bytes(base64.b64decode(self.data["positive_stage"][name]))
        ci.settled_stages(self.root, {"stages": [row]}, [label])
        row["cleanup_limit_seconds"] = 4
        (folder / "receipt.json").write_bytes(encoded(row))
        with self.assertRaisesRegex(ValueError, "did not settle"):
            ci.settled_stages(self.root, {"stages": [row]}, [label])


